CREATE TABLE inventory_guard(id BIGINT PRIMARY KEY);
INSERT INTO inventory_guard(id) VALUES(1);
CREATE TABLE inventory(variant_id BIGINT PRIMARY KEY,on_hand INT NOT NULL DEFAULT 0,reserved INT NOT NULL DEFAULT 0,minimum_stock INT NOT NULL DEFAULT 5,version BIGINT NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CHECK(on_hand>=0 AND reserved>=0 AND reserved<=on_hand AND minimum_stock>=0));
CREATE TABLE inventory_transactions(id BIGINT PRIMARY KEY AUTO_INCREMENT,variant_id BIGINT NOT NULL,operation_key VARCHAR(150) NOT NULL UNIQUE,request_hash VARCHAR(64) NOT NULL,type VARCHAR(20) NOT NULL,quantity_delta INT NOT NULL,reserved_delta INT NOT NULL,reason VARCHAR(500) NOT NULL,actor_id BIGINT NOT NULL,result_on_hand INT NOT NULL,result_reserved INT NOT NULL,result_minimum INT NOT NULL,created_at DATETIME(6) NOT NULL,FOREIGN KEY(variant_id) REFERENCES inventory(variant_id),INDEX ix_inventory_history(variant_id,created_at));
CREATE TABLE reservations(order_id VARCHAR(36) PRIMARY KEY,request_hash VARCHAR(64) NOT NULL,state VARCHAR(20) NOT NULL,expires_at DATETIME(6) NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,INDEX ix_reservation_expiry(state,expires_at),CHECK(state IN ('HELD','COMMITTED','RELEASED','EXPIRED','RESTOCKED')));
CREATE TABLE reservation_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id VARCHAR(36) NOT NULL,variant_id BIGINT NOT NULL,quantity INT NOT NULL,UNIQUE(order_id,variant_id),FOREIGN KEY(order_id) REFERENCES reservations(order_id),FOREIGN KEY(variant_id) REFERENCES inventory(variant_id),CHECK(quantity>0));
